'use strict';
Object.assign(sources,{
sea:['NOAA JetStream · The sea breeze','https://www.noaa.gov/jetstream/ocean/sea-breeze'],fine:['NOAA glossary · Sea-breeze fine lines','https://www.noaa.gov/jetstream/appendix/weather-glossary-s'],lake:['NWS Binghamton · Lake shadow & breeze','https://www.weather.gov/bgm/WeatherInActionLakeShadowBreeze'],terrain:['NASA GPM · Mountains and precipitation measurement','https://gpm.nasa.gov/resources/faq/what-effect-do-mountainous-orographic-regions-have-measuring-precipitation'],ash:['USGS · Redoubt Doppler radar observations, 2009','https://www.usgs.gov/publications/doppler-weather-radar-observations-2009-eruption-redoubt-volcano-alaska'],wake:['NOAA NESDIS · Guadalupe Island vortices','https://www.nesdis.noaa.gov/news/earth-orbit-von-karman-vortices'],waves:['NOAA NESDIS · Wave clouds','https://www.nesdis.noaa.gov/our-environment/clouds/wave-clouds'],gravity:['NWS · Atmospheric gravity waves','https://www.weather.gov/source/zhu/ZHU_Training_Page/Miscellaneous/gravity_wave/gravity_wave.html'],dust:['NWS Phoenix · Historic dust storm, July 5, 2011','https://www.weather.gov/psr/Jul52011'],turbines:['NWS Radar Operations Center · Wind-farm impacts','https://www.roc.noaa.gov/windfarms/wf-impact.php'],bright:['NWS Jackson · Dual-pol applications','https://www.weather.gov/jan/dualpolupgrade-applications'],hail:['NWS Louisville · Three-body scatter spike','https://www.weather.gov/lmk/nws_radar_ref-hail-spike'],sample:['NWS Louisville · Radar sampling issues','https://www.weather.gov/lmk/radar_sample'],virga:['NWS Louisville · Echoes without surface precipitation','https://www.weather.gov/lmk/VirgaExplainedGraphically?tp=1'],clear:['NWS Northern Indiana · Weather and non-weather echoes','https://www.weather.gov/iwx/wsr_88d'],boundary:['Lee County hydrological monitoring · NEXRAD','https://www.leegov.com/naturalresources/hydrological-monitoring/rainfall/nexrad'],dryline:['Monthly Weather Review · Wyoming dryline, June 22, 2010','https://journals.ametsoc.org/view/journals/mwre/142/1/mwr-d-13-00049.1.xml'],rolls:['NWS Central Region · Convective-roll case study','https://www.weather.gov/media/crh/publications/TA/TA_0501.pdf'],mod:['NOAA · Fact check: weather modification claims','https://www.noaa.gov/news/fact-check-debunking-weather-modification-claims'],wmo:['WMO · Statement on weather modification, 2025','https://wmo.int/content/wmo-statement-weather-modification'],haarp:['University of Alaska Fairbanks · HAARP FAQ','https://haarp.gi.alaska.edu/faq'],quake:['USGS · Is there earthquake weather?','https://www.usgs.gov/faqs/there-earthquake-weather'],contrail:['EPA · Contrails from aircraft','https://www.epa.gov/regulations-emissions-vehicles-and-engines/Contrails'],fallstreak:['NOAA NESDIS · Fallstreak clouds','https://www.nesdis.noaa.gov/fallstreak-clouds'],reports:['NOAA Library · Weather modification project reports','https://library.noaa.gov/weather-climate/weather-modification-project-reports']});
// Curated teaching entries: regional assignments describe relevant settings, not measured occurrence rates.
const phenomena=[];
function P(id,title,category,instrument,shape,summary,cause,check,trap,settings,season,refs,caseId){phenomena.push({id,title,category,instrument,shape,summary,cause,check,trap,settings,season,refs,caseId})}
P('seabreeze','Sea-breeze front','Boundaries','Radar + surface observations','sea','A thin coastal line advances inland, sometimes before storms develop.','Cool marine air advances toward warmer land; insects concentrated along the convergence zone can reveal the front.','Compare coastline orientation, onshore winds, daytime heating, and surface temperature changes.','A visible boundary can help initiate storms. Seeing it first does not mean a radar created it.',['coast','island'],'Warm, sunny days; timing varies with background wind.',['sea','fine']);
P('lakebreeze','Lake-breeze boundary','Boundaries','Radar + satellite + surface','sea','Large lakes can organize a shoreline boundary and a band of clouds.','Water and land heat differently, producing a local circulation when conditions permit.','Check lakeshore winds and temperature, cloud development, and whether a radar fine line is actually present.','A cloud boundary in a satellite picture is not necessarily a detectable radar return.',['lakes'],'Often warm-season daytime; depends on wind and stability.',['lake','boundary']);
P('outflow','Outflow & gust fronts','Boundaries','Radar + surface observations','arc','A curved fine line spreads away from a thunderstorm.','Storm-cooled air spreads outward; suspended scatterers can outline its leading edge.','Trace the line back through a loop to its parent storm. Look for a surface wind shift and temperature drop.','An expanding arc is not evidence of an artificial blast.',['all'],'During and after thunderstorms, in any season.',['boundary']);
P('dryline','Dryline fine line','Boundaries','Radar + surface dewpoint','line','A narrow echo can trace the meeting of dry and humid air.','Converging winds concentrate insects along the moisture boundary.','Compare dewpoints and winds on both sides; a radar line by itself cannot identify a dryline.','Radar is detecting scatterers, not directly painting a wall of humidity.',['plains','interior'],'Especially warm-season afternoons on the Plains.',['dryline']);
P('rolls','Horizontal convective rolls','Boundaries','Radar + satellite','parallel','Parallel fine lines may line up with cloud streets.','Organized boundary-layer circulations can concentrate biological scatterers in bands.','Compare the orientation with low-level wind and satellite cloud streets; inspect the evolution.','Regular spacing does not establish engineering or a grid of transmitters.',['all'],'Daytime convective boundary layers; visibility depends on scatterers.',['rolls']);
P('batroost','Bat emergence rings','Biology','Radar','ring','A ring expands outward from a known roost near dusk.','Many bats taking flight together create a growing field of backscatter.','Check the origin, time, season, nearby colonies, and dual-pol context.','Ring geometry alone does not identify bats; bird roosts can look similar.',['plains','south'],'Warm-season evenings in suitable roost habitat.',['bats'],'bats');
P('birdroost','Bird roost rings','Biology','Radar','ring','A localized dawn ring spreads from a shared overnight roost.','Groups of birds leave together and disperse to feed.','Find a repeatable roost origin and sunrise timing; compare biological observations.','A circular return is not automatically rain or a propagating energy pulse.',['all','lakes'],'Seasonal roosting periods, often around sunrise.',['odd'],'birds');
P('migration','Broad bird migration','Biology','Radar','bloom','Broad, weak returns can blossom after sunset.','Migrating birds occupy a large volume of air that sensitive radars can sample.','Compare nocturnal timing, successive scans, winds, and migration context.','Radar reflectivity alone cannot give a reliable species identification or head count.',['all'],'Especially spring and autumn nights.',['clear']);
P('insects','Insect clear-air echoes','Biology','Radar','bloom','Weak echoes appear even with no rain-bearing cloud overhead.','Many insects provide detectable backscatter and can act as tracers of low-level airflow.','Compare sensitive scans, warm-season conditions, and boundary structure.','“Clear air” mode does not mean that radar is directly displaying invisible radio waves.',['all'],'Often warmer months when insects are active.',['clear']);
P('blockage','Mountain beam blockage','Terrain & water','Radar','mountain','A persistent wedge may be weak or empty behind terrain.','High ground intercepts part or all of the beam before it reaches a more distant region.','Compare terrain, beam elevation, neighboring radars, and gauges.','A missing wedge is not proof that rain stopped at an invisible wall.',['mountains'],'Persistent geometry; impact depends on scan angle and weather depth.',['terrain']);
P('terrainclutter','Mountain & building clutter','Terrain & water','Radar','clutter','Fixed, patchy echoes line up with nearby surface features.','Radar energy reaches terrain or structures and scatters back.','Compare fixed location across scans, terrain, velocity, and clutter-filter differences.','A return near a mountain does not show that the mountain is erupting.',['mountains','all'],'Possible year-round; propagation conditions change its prominence.',['ap']);
P('orographic','Orographic rain & rain shadows','Terrain & water','Radar + gauges + satellite','mountain','Wet slopes and drier lee areas can form real geographic contrasts.','Flow rising over terrain can enhance precipitation; descending air can favor drying.','Combine winds and gauges with terrain and radar coverage limitations.','Real rain shadows and radar shadows are different explanations that must be tested separately.',['mountains','island'],'Depends on moisture supply and wind direction, not just season.',['terrain']);
P('seaclutter','Sea-surface returns','Terrain & water','Radar','sea','Low coastal beams may receive echoes from ocean waves.','Rough water scatters energy, much like unwanted ground returns on land.','Check near-coastal geometry, surface conditions, persistence, and other observations.','Offshore color does not establish an underwater eruption or weapon.',['coast','island'],'Depends on radar siting, waves, and atmospheric propagation.',['clear']);
P('ash','Volcanic eruption columns','Terrain & water','Specialized/weather radar + satellite','volcano','An explosive eruption can loft radar-detectable particles.','Ash, larger tephra, and ice-coated particles can scatter radio waves; not every ash cloud is detectable.','Require volcano-observatory evidence and compare seismic, camera, satellite, and radar information.','An echo near a volcano alone cannot confirm an eruption or identify fine ash.',['volcanic'],'Event-driven, not a seasonal radar phenomenon.',['ash']);
P('islandwake','Island vortex streets','Waves & clouds','Satellite · not primarily radar','vortex','Alternating cloud swirls trail downstream of an island.','Flow past an obstacle can shed a repeating sequence of vortices, made visible by clouds.','Identify the island, wind direction, cloud layer, and satellite channel.','A classic satellite vortex street should not be presented as a Doppler-radar anomaly.',['island','coast'],'Needs suitable flow, stability, and a visible cloud layer.',['wake']);
P('mountainwave','Mountain wave clouds','Waves & clouds','Satellite + visual observations','wave','Cloud bands can remain aligned with terrain while air flows through them.','Stable air displaced over high terrain can oscillate downstream.','Compare ridge orientation, winds aloft, stability, and cloud motion.','Waves in air are real; a wave pattern does not identify a radio-frequency cause.',['mountains','island'],'Appropriate stable flow; possible in many seasons.',['waves']);
P('gravity','Gravity waves & bores','Waves & clouds','Radar in some cases + satellite','wave','Ripples or bands travel through air and sometimes clouds or radar scatterers.','Buoyancy and gravity restore displaced air, allowing atmospheric waves to propagate.','Look for pressure/wind changes, coherent motion, and independent observations of a wave-supporting layer.','“Gravity wave” here means an atmospheric fluid wave, not a gravitational wave from space.',['all'],'Depends on atmospheric structure and a disturbance.',['gravity']);
P('ap','Anomalous propagation / ducting','Instrument & processing','Radar','clutter','Unexpected ground echoes can look like strong rain.','Unusual refractivity bends radar energy toward the surface.','Compare other radars, higher tilts, terrain, and temperature/moisture structure.','A changed radio path is a sensing effect, not evidence of weather generation.',['all','coast'],'Often favored by suitable stable layers; not limited to them.',['ap'],'duct');
P('sunspike','Sunrise & sunset spikes','Instrument & processing','Radar receiver','spike','A narrow radial streak briefly points toward the low sun.','Solar radio energy enters the receiving system near antenna alignment.','Compare the exact scan time and solar direction; check adjacent scans.','A radial line is not necessarily a beam actively targeting the atmosphere.',['all'],'Possible near local sunrise or sunset.',['sun'],'sun');
P('interference','Radio-frequency interference','Instrument & processing','Radar receiver','spike','Spokes or radial streaks contaminate an image.','An unwanted signal enters the receiver; some cases have an identified external radio source.','Check maintenance notes, affected radials, persistence, and independent instrumentation.','Interference is real. Its appearance does not demonstrate control of storms.',['all'],'Equipment/source dependent; no general season.',['emi'],'emi');
P('chaff','Aircraft chaff','Human-made targets','Radar','plume','A drifting return can mimic a patch of rain.','Radar-reflective fibers released by aircraft scatter strongly while dispersing.','Compare polarimetric information and documented activity; require evidence for a particular attribution.','A non-weather echo does not by itself demonstrate cloud seeding or toxic spraying.',['all','coast'],'Activity and wind dependent; no universal season.',['chaff'],'chaff');
P('turbines','Wind-turbine contamination','Human-made targets','Radar','clutter','A fixed wind farm can contaminate reflectivity and velocity.','Moving blades scatter radar energy and can interfere with derived products.','Compare turbine locations, radar line of sight, elevation, and repeatability.','A stationary contaminated patch is not a newly forming rotating storm.',['plains','interior'],'Persistent siting issue; depends on beam intersection and turbine operation.',['turbines']);
P('brightband','Melting-layer bright band','Precipitation & storms','Radar + vertical context','ring','A bright arc or ring can appear inside broader precipitation.','Partially melted snow scatters strongly where the beam crosses the melting layer.','Compare multiple tilts and the corresponding ZDR/CC signatures.','A bright ring need not mean more rain at the surface.',['all'],'Often stratiform precipitation with a sampled melting layer.',['bright']);
P('hailspike','Three-body scatter / hail spike','Precipitation & storms','Radar','hail','A weak spike extends radially behind an intense hail core.','An indirect path involving hail, the ground, and hail again delays the echo.','Check that it lies downrange of the strong storm core and compare other storm evidence.','The spike is not a plume of material physically stretched behind the storm.',['all','plains'],'Intense hailstorms; not present in every hailstorm.',['hail']);
P('alias','Velocity folding','Instrument & processing','Radar velocity','velocity','Adjacent colors can jump between opposite ends of a speed scale.','Speeds outside the unambiguous velocity interval wrap into a different displayed interval.','Check the legend, surrounding flow, neighboring scans, and dealiasing.','An abrupt red/green jump is not automatically a tornado.',['all'],'Sampling-dependent; possible with sufficiently strong radial speeds.',['sample','velocity']);
P('rangefold','Range folding','Instrument & processing','Radar','spike','An echo is ambiguous or assigned to an incorrect apparent range.','A late echo from an earlier pulse is confused with the timing of a later pulse.','Compare other elevations, scan strategies, and nearby radars.','Missing or flagged data is not a hidden storm being deliberately erased.',['all'],'Depends on pulse timing and distant scatterers.',['sample']);
P('virga','Virga: rain aloft, dry ground','Precipitation & storms','Radar + surface observations','rain','Radar detects precipitation that never reaches the observer below.','Drops evaporate or ice sublimates in dry air beneath a cloud.','Check the dry lower atmosphere, gauges, and visual shafts fading before the ground.','The radar can be correctly observing precipitation while the pavement stays dry.',['all','interior'],'Any time a sufficiently dry layer lies below precipitation.',['virga']);
P('smoke','Fire plumes & lofted material','Particles & plumes','Radar + satellite + fire reports','plume','A plume extends downwind of a known fire.','A fire can loft radar-detectable particles; radar does not directly map all smoke or invisible gases.','Compare active-fire reports, cameras, satellite imagery, and the wind.','A return is not a chemical analysis or a measure of breathing-level air quality.',['all','mountains'],'Fire and wind dependent; regional fire seasons differ.',['odd']);
P('dust','Haboobs & dust fronts','Particles & plumes','Radar + surface observations','arc','A storm-driven wall of dust can form a broad moving arc.','Strong outflow winds lift sediment from dry ground.','Check storm outflow, surface visibility and wind, reports, and photographs.','A colored radar arc is not sufficient to tell dust from every other boundary.',['desert','plains'],'Often warm-season thunderstorm outflows in dry regions.',['dust']);
P('debris','Tornado debris signature','Precipitation & storms','Radar, multiple products','velocity','Strong rotation and a matching drop in target consistency occur together.','Lofted debris adds many shapes and sizes to the sampled volume.','Co-locate the velocity couplet, CC drop, and storm echo; use the original sequence.','Low CC alone is insufficient, and absence of a debris signature does not rule out a tornado.',['all'],'Tornado events; visibility depends on lofted debris and beam height.',['dual'],'debris');
const phenomenonById=id=>phenomena.find(p=>p.id===id);
let atlasFilter='All',atlasQuery='',atlasInstrument='All',atlasStep=45,atlasAnnotations=true,atlasTimer=null,activePhenomenon=null;
function atlasPage(){const cats=['All',...new Set(phenomena.map(p=>p.category))];return pageHead('06 / SIGNATURE ATLAS','The atmosphere has<br><em>more than one signature.</em>','Thirty visual field notes on odd-looking returns, real boundaries, terrain effects, and cloud patterns. Start with the shape, then test the explanation.','RADAR ≠ SATELLITE')+`<div class="atlas-intro"><div><b>30</b><span>EXPLAINED PHENOMENA</span></div><div><b>3</b><span>WAYS TO EXPLORE</span></div><p>Search by name, filter by mechanism, or <button class="text-button" data-go="regions">start with your state →</button><br>Every entry distinguishes the instrument, the interpretation, and the limits.</p></div><div class="search-row"><input class="search" id="atlas-search" value="${escapeAttr(atlasQuery)}" placeholder="Search volcano, mountains, sea breeze, rings…" aria-label="Search signature atlas"><select id="atlas-instrument" aria-label="Filter observing instrument"><option>All</option><option ${atlasInstrument==='Radar'?'selected':''}>Radar</option><option ${atlasInstrument==='Satellite'?'selected':''}>Satellite</option></select></div><div class="filters">${cats.map(c=>`<button class="filter ${atlasFilter===c?'active':''}" data-atlas-filter="${c}">${c}</button>`).join('')}</div><div id="atlas-results">${atlasResults()}</div><div class="panel pad space"><span class="kicker">KNOW WHAT YOU’RE LOOKING AT</span><p>Cards labeled REAL RADAR or SATELLITE OBSERVATION show credited historical imagery. SCIENCE DIAGRAM cards are conceptual teaching aids. Regional labels describe physical settings, not measured frequency. Open an entry for the explanation, evidence checks, and sources.</p></div>`;}
function escapeAttr(s){return s.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;').replaceAll('>','&gt;')}
function atlasMatches(){return phenomena.filter(p=>(atlasFilter==='All'||p.category===atlasFilter)&&(atlasInstrument==='All'||(atlasInstrument==='Satellite'?p.instrument.toLowerCase().includes('satellite'):p.instrument.toLowerCase().includes('radar')))&&[p.title,p.summary,p.cause,p.category,p.shape].join(' ').toLowerCase().includes(atlasQuery.toLowerCase()))}
function atlasResults(){const arr=atlasMatches();return `<p class="status-line" role="status">${arr.length} OF ${phenomena.length} ENTRIES · OBSERVATIONS & SCIENCE DIAGRAMS</p><div class="phenomena-grid">${arr.map(p=>`<article class="signature-card"><div class="signature-visual">${signatureSVG(p,45,false)}</div><div class="pad"><span class="kicker">${p.category.toUpperCase()}</span><h2>${p.title}</h2><span class="instrument-tag">${p.instrument}</span><p>${p.summary}</p><button class="text-button" data-phenomenon="${p.id}">Read the signature ↗</button></div></article>`).join('')}</div>${arr.length?'':'<div class="empty">No matches. Try “wave”, “terrain”, or clear the filters.</div>'}`;}
function atlasDetail(id){const p=phenomenonById(id);if(!p)return;activePhenomenon=id;atlasStep=45;atlasAnnotations=true;history.replaceState(null,'','#atlas/'+id);$('#page').innerHTML=`<button class="back" id="back-atlas">← All signatures</button>`+pageHead('06 / FIELD NOTE',p.title,p.summary,p.category.toUpperCase())+`<div class="detail-grid"><div class="panel"><div class="illustration-head"><span class="kicker">SCHEMATIC CONCEPT · NOT OBSERVED DATA</span><span class="instrument-tag">${p.instrument}</span></div><div id="signature-stage">${signatureSVG(p,atlasStep,atlasAnnotations)}</div><div class="diagram-controls"><button class="square" id="signature-play" aria-label="Play schematic evolution">▶</button><label for="signature-time">Illustration phase</label><input id="signature-time" type="range" min="0" max="100" value="45"><button class="square" id="annotations" aria-pressed="true">Labels on</button></div><p class="tip diagram-note">The phase control illustrates the concept, not event timing or a quantitative forecast. Fixed terrain and instrument artifacts remain fixed.</p></div><div class="panel pad"><span class="kicker">READ THE EVIDENCE</span><h2>In plain language</h2><p>${p.summary}</p><details class="technical-note"><summary>Technical breakdown · the mechanism</summary><p>${p.cause}</p>${glossary.filter(([term])=>[p.title,p.cause,p.check,p.trap].join(" ").toLowerCase().includes(term.toLowerCase())).slice(0,3).map(([term,definition])=>`<p><b>${term}:</b> ${definition}</p>`).join("")}<p class="tip">Instrument: ${p.instrument}. Use the primary records below for the documented method and example.</p></details><div class="evidence"><strong>CHECK</strong><p>${p.check}</p></div><div class="evidence"><strong>DON’T INFER</strong><p>${p.trap}</p></div><div class="evidence"><strong>WHEN</strong><p>${p.season}</p></div><div class="row space"><button class="button secondary" data-go="regions">Explore regional context →</button><button class="text-button" data-go="myths">Visit the myth desk →</button></div></div></div><div class="source-strip"><span class="kicker">PRIMARY RECORDS & EXPLANATIONS</span>${p.refs.map(ref).join('')}${p.caseId?`<button class="text-button" data-real-case="${p.caseId}">Open documented case file ↗</button>`:''}</div><div id="observed-example"></div><div class="grid2 space"><div class="panel pad"><span class="kicker">THE QUESTION THAT MATTERS</span><h3>What else could look similar?</h3><p>${lookalike(p)}</p><button class="text-button" data-go="myths">Use the screenshot investigation checklist →</button></div><div class="panel pad"><span class="kicker">TAKE THE EXPLANATION WITH YOU</span><p>Share the field note or copy a short explanation with its source. A generic example never identifies a different screenshot by itself.</p><div class="row"><button class="button secondary" data-copy-note="${id}">Copy explanation</button><button class="text-button" data-copy-link="atlas/${id}">Copy link ↗</button></div><span class="copy-status" aria-live="polite"></span></div></div>`;bind();bindAtlasDetail(p);renderObserved(p);window.scrollTo(0,0);}
function lookalike(p){if(p.shape==='ring')return 'Bird or bat dispersal, a melting layer, radar range rings, and other circular patterns have different origins. Locate the center and compare timing, elevation, products, and independent observations.';if(['wave','parallel','vortex'].includes(p.shape))return 'Cloud bands, biological fine lines, and image-processing artifacts can all look organized. First establish whether this is radar, satellite, or a photograph.';if(['spike','hail'].includes(p.shape))return 'Solar pickup, external interference, hail scatter, and invalid or missing data can create radial-looking features. Geometry alone is insufficient.';return 'A familiar-looking shape is a starting hypothesis. Check the original loop, product, scan angle, terrain, and observations before assigning a cause.'}
function bindAtlasDetail(p){const evolving=['sea','ring','wave','parallel','arc','line','volcano','rain','plume','bloom','vortex'].includes(p.shape)&&!['brightband','seaclutter'].includes(p.id);if(!evolving){$('#signature-time').hidden=true;$('#signature-play').hidden=true;$('.diagram-controls label').hidden=true;$('.diagram-note').textContent='Fixed-geometry schematic. Toggle the labels to inspect the physical arrangement.';}$('#back-atlas').onclick=()=>go('atlas');$('#signature-time').oninput=e=>{atlasStep=+e.target.value;$('#signature-stage').innerHTML=signatureSVG(p,atlasStep,atlasAnnotations)};$('#annotations').onclick=()=>{atlasAnnotations=!atlasAnnotations;$('#annotations').textContent=atlasAnnotations?'Labels on':'Labels off';$('#annotations').setAttribute('aria-pressed',atlasAnnotations);$('#signature-stage').innerHTML=signatureSVG(p,atlasStep,atlasAnnotations)};$('#signature-play').onclick=()=>{if(atlasTimer){clearAtlasTimer();return}$('#signature-play').textContent='Ⅱ';$('#signature-play').setAttribute('aria-label','Pause schematic evolution');$('#signature-play').setAttribute('aria-pressed','true');atlasTimer=setInterval(()=>{atlasStep=(atlasStep+2)%101;$('#signature-time').value=atlasStep;$('#signature-stage').innerHTML=signatureSVG(p,atlasStep,atlasAnnotations)},170)};$$('[data-real-case]').forEach(b=>b.onclick=()=>{clearAtlasTimer();go('cases');caseDetail(b.dataset.realCase)});bindExtendedLinks();}
function clearAtlasTimer(){clearInterval(atlasTimer);atlasTimer=null;const play=$('#signature-play');if(play){play.textContent='▶';play.setAttribute('aria-label','Play schematic evolution');play.setAttribute('aria-pressed','false')}}
function signatureSVG(p,step,labels){const t=step/100;let art='',notes='',base=`<defs><pattern id="smallgrid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#73925d18"/></pattern></defs><rect width="600" height="320" fill="#111d17"/><rect width="600" height="320" fill="url(#smallgrid)"/>`;const txt=(x,y,s)=>`<text x="${x}" y="${y}" fill="#d9e8be" font-size="11">${s}</text>`;const line=(x,y,xx,yy,col='#d0ed80')=>`<path d="M${x} ${y}L${xx} ${yy}" stroke="${col}" fill="none" stroke-width="2"/>`;
if(p.shape==='ring'){const r=p.id==='brightband'?95:38+t*85;art=`<circle cx="290" cy="165" r="${r}" fill="none" stroke="#82c477" stroke-width="12" opacity=".7"/>${p.id==='brightband'?'<circle cx="290" cy="165" r="70" fill="#598a8444"/>':''}<circle cx="290" cy="165" r="4" fill="#d0ed80"/>`;notes=txt(25,35,p.id==='brightband'?'BEAM INTERSECTS MELTING LAYER':'DISPERSAL FROM A SHARED ORIGIN')+line(290,165,410,250)+txt(360,275,p.id==='brightband'?'RADAR CENTER':'ROOST');}
else if(p.shape==='mountain'){art=`<path d="M0 270L85 255L155 98L225 248L310 180L390 265L600 260V320H0Z" fill="#526548"/><path d="M40 245L155 185L590 65L590 235L155 220Z" fill="#d0ed8022"/>${p.id==='blockage'?'<path d="M155 190L590 65V235L170 218Z" fill="#080f0cbb"/>':''}${p.id==='orographic'?'<path d="M60 165Q130 50 190 125" fill="none" stroke="#83c4a3" stroke-width="25"/><g stroke="#77b8bd" stroke-width="2"><path d="M90 135l-15 40M110 130l-15 40M130 130l-15 40"/></g>':''}<circle cx="40" cy="245" r="6" fill="#d0ed80"/>`;notes=txt(25,32,p.id==='blockage'?'TERRAIN INTERCEPTS THE BEAM':'TERRAIN SHAPES BOTH FLOW AND COVERAGE')+txt(30,290,'RADAR')+txt(330,280,p.id==='orographic'?'LEE SIDE':'CHECK OTHER RADARS / GAUGES');}
else if(p.shape==='volcano'){art=`<path d="M70 300L245 180L270 190L295 180L460 300Z" fill="#68715a"/><path d="M250 185C235 130 ${205-t*45} 85 ${245-t*30} 55Q300 5 350 50T510 85Q420 135 305 145L290 185Z" fill="#a3b49866"/><path d="M80 230L430 75L545 170Z" fill="#d0ed8018"/><circle cx="80" cy="230" r="5" fill="#d0ed80"/>`;notes=txt(20,32,'SCATTERING PARTICLES IN AN ERUPTION COLUMN')+txt(315,225,'RADAR + OBSERVATORY EVIDENCE');}
else if(p.shape==='vortex'){art=`<path d="M60 140Q70 80 100 150L120 205H40Z" fill="#6a7956"/>`;for(let i=0;i<6;i++){const x=160+i*67+t*25,y=155+(i%2?38:-28),r=23;art+=`<path d="M${x-r} ${y}c0 -34 48 -34 48 0s-40 28 -35 -2s28 -13 22 4" stroke="#cbdcc6" fill="none" stroke-width="8" opacity=".7"/>`}notes=txt(20,32,'SATELLITE / CLOUD TRACERS IN THE ISLAND WAKE')+txt(35,240,'ISLAND')+txt(260,270,'WIND →');}
else if(p.shape==='wave'||p.shape==='parallel'){for(let i=0;i<6;i++){const x=90+i*75+t*30;art+=`<path d="M${x} 70Q${x+35} 150 ${x-10} 250" fill="none" stroke="${p.shape==='wave'?'#b6d4c7':'#8dbf63'}" stroke-width="${p.shape==='wave'?15:5}" opacity=".65"/>`}notes=txt(20,32,p.shape==='wave'?'ATMOSPHERIC WAVES / MECHANISM DEPENDS ON CONTEXT':'ORGANIZED BOUNDARY-LAYER BANDS')+txt(150,285,'REGULAR SPACING ≠ ARTIFICIAL ORIGIN');}
else if(p.shape==='sea'){art=`<path d="M0 0H195Q230 100 185 160T190 320H0Z" fill="#213e43"/><path d="M195 0Q230 100 185 160T190 320" fill="none" stroke="#719384" stroke-width="2"/>`;if(p.id!=='seaclutter'){const x=225+t*110;art+=`<path d="M${x} 45Q${x+45} 165 ${x-5} 270" stroke="#a8cf7d" stroke-width="5" fill="none"/>`;notes=txt(20,32,'LAND–WATER HEATING CONTRAST')+txt(45,280,'WATER')+txt(380,280,'LAND')+txt(320,90,'BOUNDARY →');}else {for(let i=0;i<25;i++)art+=`<circle cx="${60+(i*47)%140}" cy="${70+(i*63)%170}" r="6" fill="#73a88a" opacity=".6"/>`;notes=txt(25,32,'SURFACE RETURNS ARE NOT NECESSARILY RAIN');}}
else if(p.shape==='arc'){const x=210+t*95;art=`<path d="M100 75Q270 110 130 220" fill="none" stroke="#4c9480" stroke-width="55" opacity=".5"/><path d="M${x} 40Q${x+195} 165 ${x} 290" fill="none" stroke="${p.id==='dust'?'#c9b478':'#b4db7a'}" stroke-width="8"/>`;notes=txt(25,32,p.id==='dust'?'DUST LIFTED BY THUNDERSTORM OUTFLOW':'EXPANDING LEADING EDGE OF STORM-COOLED AIR')+txt(330,290,'MOTION →');}
else if(p.shape==='line'){art=`<path d="M${245+t*25} 40Q310 150 245 280" fill="none" stroke="#9dc870" stroke-width="7"/>${[90,160,230].map(y=>line(150,y,235,y)+line(420,y,310,y)).join('')}`;notes=txt(25,32,'CONVERGENCE GATHERS SCATTERERS')+txt(65,300,'COMPARE SURFACE MOISTURE AND WIND');}
else if(p.shape==='spike'||p.shape==='hail'){art=`<circle cx="125" cy="220" r="4" fill="#d0ed80"/><path d="M125 220L565 90L565 105Z" fill="#88b68c99"/>`;if(p.shape==='hail')art+=`<ellipse cx="330" cy="158" rx="47" ry="33" fill="#e7a957"/><ellipse cx="330" cy="158" rx="23" ry="18" fill="#d36855"/>`;notes=txt(25,32,p.shape==='hail'?'DELAYED MULTIPATH ECHO BEHIND A HAIL CORE':'RADIAL ARTIFACT / CAUSE NEEDS CONTEXT')+txt(75,255,'RADAR')+txt(380,260,p.shape==='hail'?'APPARENT RANGE →':'COMPARE TIME / DIRECTION');}
else if(p.shape==='clutter'){art=`<circle cx="285" cy="175" r="100" fill="none" stroke="#d0ed8025"/>`;for(let i=0;i<40;i++){const x=155+(i*73)%240,y=70+(i*57)%190;art+=`<rect x="${x}" y="${y}" width="${5+i%8}" height="${5+i%9}" fill="${i%3?'#70ac79':'#c6cc67'}" opacity=".6"/>`}notes=txt(25,32,'FIXED / PATCHY CONTAMINATION')+txt(155,290,'COMPARE GEOGRAPHY AND SCAN ANGLES');}
else if(p.shape==='velocity'){art=`<ellipse cx="280" cy="165" rx="95" ry="70" fill="#48b97b88"/><ellipse cx="360" cy="165" rx="45" ry="70" fill="#dc826caa"/><path d="M315 80V250" stroke="#eee8ce" stroke-dasharray="4 6"/>`;notes=txt(25,32,p.id==='alias'?'COLOR WRAPPING CAN MIMIC A SHARP CHANGE':'ROTATION NEEDS MATCHING PRODUCTS')+txt(110,285,'GREEN = TOWARD / RED = AWAY IN THIS PALETTE');}
else if(p.shape==='rain'){art=`<ellipse cx="290" cy="85" rx="130" ry="35" fill="#7c9985"/>`;for(let i=0;i<12;i++){const x=180+i*20;art+=`<path d="M${x} 115l-15 ${55+t*35}" stroke="#85b5b6" stroke-width="2" opacity="${.3+(i%4)*.15}"/>`}art+='<path d="M30 280H570" stroke="#8b9e69"/>';notes=txt(25,32,'PRECIPITATION ALOFT / EVAPORATION BELOW')+txt(175,255,'DRY LOWER AIR');}
else if(p.shape==='plume'){const x=180+t*65;art=`<path d="M140 240Q${x} 180 330 115T550 70L540 125Q320 170 150 250Z" fill="#9bb28a77"/><circle cx="140" cy="245" r="9" fill="#e0ae60"/>`;notes=txt(25,32,'A WIND-TRANSPORTED RETURN')+txt(330,270,'COMPARE INDEPENDENT SOURCE REPORTS');}
else{for(let i=0;i<50;i++){const x=100+(i*71)%390,y=60+(i*53)%190;art+=`<circle cx="${x}" cy="${y}" r="${5+t*9}" fill="#5e9e8c" opacity=".35"/>`}notes=txt(25,32,'WEAK BACKSCATTER OVER A BROAD AREA')+txt(140,290,'TIMING AND OTHER PRODUCTS MATTER');}
return `<svg class="signature-svg" viewBox="0 0 600 320" role="img" aria-label="Schematic of ${p.title}, not an observed scan">${base}${art}${labels?notes:''}<text x="20" y="309" fill="#8b9e80" font-size="8">SCHEMATIC · ${p.instrument.toUpperCase().replaceAll('&','&amp;')}</text></svg>`;}
const myths=[
{id:'radar-steering',topic:'Weather control',claim:'NEXRAD is steering or strengthening the storm.',verdict:'Contradicted by the instrument’s function',fact:'Weather radar observes echoes and motion. It cannot direct a hurricane or move an air mass.',reason:'A nearby radar symbol is an observing location, not a storm-control mechanism.',test:'Compare the storm’s motion with independently measured winds and the broader weather pattern.',refs:['mod'],related:['interference','outflow']},
{id:'rings',topic:'Radar shapes',claim:'Those expanding radar rings are energy pulses making weather.',verdict:'The shape does not establish that cause',fact:'Biological dispersal and melting-layer effects can produce rings. The loop, center, and products distinguish them.',reason:'The display is a reconstruction of sampled echoes, not a video of transmitted radio waves.',test:'Locate the center, check dawn/dusk timing, compare elevation angles and dual-pol, and identify any actual roost.',refs:['bats','bright'],related:['batroost','brightband','birdroost']},
{id:'sixg',topic:'Weather control',claim:'A “6G wave” appeared on radar, then storms formed—so the wave created them.',verdict:'Unsupported causal inference',fact:'An approaching boundary can precede storms. That sequence does not identify a telecommunications source.',reason:'Storm formation along a convergence boundary has a physical meteorological explanation.',test:'Recover timestamps and winds. Test sea-breeze or outflow explanations against independent observations; require a specified, measurable mechanism for the radio claim.',refs:['sea','boundary','mod'],related:['seabreeze','outflow','gravity']},
{id:'haarp-weather',topic:'Weather control',claim:'HAARP controls surface weather or sends hurricanes to a target.',verdict:'Contradicted by the research system’s operation',fact:'HAARP studies the ionosphere. Its radio transmissions do not provide a way to control tropospheric weather.',reason:'Sharing the word “wave” does not make ionospheric radio research a mechanism for moving storms.',test:'Ask which atmospheric layer, interaction, energy transfer, and independently measured response the claim specifies.',refs:['haarp'],related:['gravity','sunspike']},
{id:'seeding',topic:'Weather control',claim:'Cloud seeding proves people can manufacture or steer hurricanes.',verdict:'A real technique, extended beyond its evidence',fact:'Cloud seeding exists under suitable cloud conditions. That does not establish hurricane creation or steering.',reason:'WMO reports no generally accepted evidence of tropical-cyclone modification.',test:'Separate a specific seeding project, its measured outcome, and a hurricane-control claim. They require different evidence.',refs:['wmo','reports'],related:['chaff']},
{id:'no-modification',topic:'Weather control',claim:'Any human effect on clouds is impossible, so every modification claim is false.',verdict:'An overstatement',fact:'Cloud seeding is a real, limited practice. Aircraft can also trigger fallstreak holes in suitable supercooled clouds.',reason:'A valid rebuttal addresses the specific mechanism and scale rather than denying all atmospheric effects.',test:'Check actual project records and cloud conditions; distinguish local cloud microphysics from hurricane control.',refs:['wmo','fallstreak','reports'],related:['seabreeze']},
{id:'straight-lines',topic:'Radar shapes',claim:'Nature does not make straight lines or regular waves.',verdict:'False as a general rule',fact:'Atmospheric boundaries, organized rolls, and wave clouds can produce highly regular patterns.',reason:'Order is a property of many fluid systems; it is not a signature of human origin.',test:'Identify radar versus satellite, inspect the wind, and watch the sequence rather than a cropped still.',refs:['rolls','waves'],related:['rolls','mountainwave','dryline']},
{id:'island-machine',topic:'Terrain & islands',claim:'Spirals behind an island reveal a weather machine.',verdict:'A known natural flow pattern fits',fact:'Island wakes can shed alternating vortices that become visible in cloud layers.',reason:'The familiar vortex street is usually shown in satellite imagery, not Doppler radar.',test:'Locate the obstacle upstream and compare prevailing winds, cloud height, and satellite channel.',refs:['wake'],related:['islandwake','mountainwave']},
{id:'volcano',topic:'Terrain & islands',claim:'An odd echo over a volcano proves an eruption.',verdict:'Insufficient evidence from an echo alone',fact:'Eruptions can produce detectable particles, but terrain, clouds, and propagation can also affect the display.',reason:'Radar contributes to volcano monitoring; it does not replace confirmation from other instruments.',test:'Compare observatory reports, cameras, seismic information, and satellite data with the original radar sequence.',refs:['ash','terrain'],related:['ash','terrainclutter','blockage']},
{id:'dry-ground',topic:'Radar interpretation',claim:'The radar shows rain but my street is dry, so the data is fake.',verdict:'There are several testable explanations',fact:'Radar can detect virga aloft. Non-weather echoes, scan height, and timing can also explain the mismatch.',reason:'A radar pixel is a sampled volume above the surface, not a rain gauge on the pavement.',test:'Check scan time, beam height, gauges, and whether precipitation evaporates in dry lower air.',refs:['virga','beam'],related:['virga','insects','blockage']},
{id:'lowcc',topic:'Radar interpretation',claim:'Any low-CC spot proves tornado debris or chaff.',verdict:'One measurement is not a unique identification',fact:'Mixed precipitation, biological targets, debris, and weak data can all lower CC.',reason:'For a debris signature, the CC reduction must match strong rotation and storm context.',test:'Compare velocity, reflectivity, data quality, and nearby tilts at the exact same location and time.',refs:['dual','products'],related:['debris','chaff','brightband']},
{id:'erased',topic:'Radar interpretation',claim:'A missing wedge or a difference between apps proves someone erased weather.',verdict:'The mismatch alone is not evidence of tampering',fact:'Terrain blockage, sampling, filtering, and product differences can change how echoes appear.',reason:'A single-radar image and a processed mosaic are different products.',test:'Match radar, product, elevation, timestamp, palette, and processing. Then compare neighboring radars and gauges.',refs:['terrain','sample','chaff'],related:['blockage','ap','rangefold']},
{id:'quake',topic:'Coincidence & clouds',claim:'A radar oddity followed by an earthquake proves they share a cause.',verdict:'Sequence is not causation',fact:'Two nearby events need a tested physical connection; their order alone is not one.',reason:'USGS finds no special “earthquake weather” distribution. That does not settle every possible interaction, but it defeats a simple weather omen.',test:'Verify the earthquake record and radar event independently, examine ordinary rates, and specify the proposed mechanism.',refs:['quake'],related:['gravity','interference']},
{id:'contrails',topic:'Coincidence & clouds',claim:'A trail that persists or spreads must be chemical spraying.',verdict:'Persistence alone does not show that',fact:'Aircraft contrails can persist and grow when the upper atmosphere is sufficiently cold and humid.',reason:'Conditions at flight altitude differ from surface humidity. Lifespan is not a chemical assay.',test:'Check flight-altitude weather and aircraft context. Claims of a particular substance need direct, reliable sampling.',refs:['contrail'],related:['mountainwave']},
{id:'cloud-holes',topic:'Coincidence & clouds',claim:'A circular hole in the clouds is a beam burning through the sky.',verdict:'A recognized cloud process can explain it',fact:'Aircraft passing through suitable supercooled cloud can trigger ice formation and a fallstreak hole.',reason:'A human-triggered microphysical effect does not imply a directed-energy weapon.',test:'Confirm the cloud type, subfreezing conditions, original imagery, and any aircraft context.',refs:['fallstreak'],related:['mountainwave']}
];
let mythFilter='All',mythQuery='';
function mythsPage(){return pageHead('08 / THE MYTH DESK','Good questions deserve<br><em>better evidence.</em>','A calm place to take apart dramatic weather claims. Separate the observed pattern from the story attached to it—and be precise about what we know.','CURIOUS. SKEPTICAL. SPECIFIC.')+`<div class="myth-feature"><div><span class="kicker">THE MOST USEFUL FIRST QUESTION</span><h2>“What would this image look like<br>if the ordinary explanation were true?”</h2><p>Compare competing explanations. Don’t mistake a familiar shape for proof, or replace an unsupported claim with an unsupported debunk.</p></div><button class="button secondary" id="jump-investigate">Check a screenshot ↓</button></div><div class="search-row"><input class="search" id="myth-search" value="${escapeAttr(mythQuery)}" placeholder="Search HAARP, 6G, rings, hurricanes, cloud seeding…" aria-label="Search weather claims"><span class="scan-badge">${myths.length} CLAIM FILES</span></div><div class="filters">${['All',...new Set(myths.map(m=>m.topic))].map(f=>`<button class="filter ${mythFilter===f?'active':''}" data-myth-filter="${f}">${f}</button>`).join('')}</div><div id="myth-results">${mythResults()}</div>${investigationHTML()}<div class="panel pad space"><span class="kicker">EDITORIAL STANDARD</span><h3>Firm on the evidence. Honest about the limits.</h3><p>“Unsupported” is different from “demonstrated false.” An alternative explanation must fit the actual event, not merely resemble a screenshot. Every file links to primary agency guidance or original research. Reviewed October 29, 2026; this is a curated reference, not an automated claim-verification service.</p></div>`;}
function mythResults(){const arr=myths.filter(m=>(mythFilter==='All'||m.topic===mythFilter)&&Object.values(m).join(' ').toLowerCase().includes(mythQuery.toLowerCase()));return `<p class="status-line" role="status">${arr.length} CLAIM FILES</p><div class="myth-grid">${arr.map((m,i)=>`<article class="myth-card"><span class="kicker">${m.topic.toUpperCase()}</span><h2>“${m.claim}”</h2><div class="verdict">${m.verdict}</div><p>${m.fact}</p><button class="text-button" data-myth="${m.id}">Follow the evidence ↗</button></article>`).join('')}</div>${arr.length?'':'<p class="empty">No matches. Try a shorter phrase or a different topic.</p>'}`;}
function mythDetail(id){const m=myths.find(m=>m.id===id);if(!m)return;history.replaceState(null,'','#myths/'+id);$('#page').innerHTML=`<button class="back" id="back-myths">← All claim files</button>`+pageHead('08 / CLAIM FILE','Check the claim.<br><em>Keep the curiosity.</em>',m.topic,'EVIDENCE FILE')+`<article class="panel pad myth-detail"><span class="kicker">THE CLAIM</span><h2>“${m.claim}”</h2><div class="verdict">${m.verdict}</div><div class="evidence"><strong>THE FACTS</strong><p>${m.fact}</p></div><div class="evidence"><strong>WHY</strong><p>${m.reason}</p></div><div class="evidence"><strong>HOW TO TEST</strong><p>${m.test}</p></div><div class="source-strip">${m.refs.map(ref).join('')}</div><div class="row space"><button class="button" data-copy-myth="${m.id}">Copy a sourced response</button><button class="button secondary" data-copy-link="myths/${m.id}">Copy link ↗</button></div><span class="copy-status" aria-live="polite"></span></article><div class="section-heading"><h2>Understand the patterns behind the claim</h2></div><div class="next-grid">${m.related.map(id=>{const p=phenomenonById(id);return `<button class="next-card" data-phenomenon="${id}"><span class="number">${p.instrument}</span><h3>${p.title}</h3><p>${p.summary}</p></button>`}).join('')}</div><div class="callout">This file addresses a general claim. It does not identify an unseen screenshot or certify the cause of an unrelated event.</div>`;$('#back-myths').onclick=()=>go('myths');bindExtendedLinks();window.scrollTo(0,0);}
function investigationHTML(){return `<section class="panel pad space" id="investigate"><div class="section-top"><span class="kicker">THE SCREENSHOT INVESTIGATOR</span><span class="pill">LOCAL CHECKLIST</span></div><h2>Start with the missing context.</h2><p class="prose">Choose what the image actually shows. This guide suggests next checks; it cannot authenticate an image or identify its cause automatically.</p><div class="grid3"><div><label for="image-type" class="form-label">1 / WHAT INSTRUMENT?</label><select class="form-select" id="image-type"><option value="unknown">I don’t know</option><option value="radar">Weather radar</option><option value="satellite">Satellite imagery</option><option value="photo">A photograph or video</option></select></div><div><label for="image-shape" class="form-label">2 / WHAT PATTERN?</label><select class="form-select" id="image-shape"><option value="ring">Ring or expanding circle</option><option value="line">Thin line or moving arc</option><option value="wedge">Missing wedge or fixed patch</option><option value="spike">Radial spike or spokes</option><option value="plume">Plume near terrain or a fire</option><option value="wave">Waves, stripes, or spirals</option></select></div><div><label for="image-context" class="form-label">3 / ORIGINAL TIME & PRODUCT?</label><select class="form-select" id="image-context"><option value="missing">Missing or uncertain</option><option value="known">Known, with original source</option></select></div></div><div class="row space"><button class="button" id="investigate-run">Build my investigation steps →</button><button class="text-button" id="copy-checklist">Copy general checklist</button></div><div id="investigation-output" aria-live="polite"></div></section>`;}
function runInvestigation(){const type=$('#image-type').value,shape=$('#image-shape').value,context=$('#image-context').value;const routes={ring:['birdroost','batroost','brightband'],line:['seabreeze','outflow','dryline'],wedge:['blockage','terrainclutter','ap'],spike:['sunspike','interference','hailspike'],plume:['ash','smoke','chaff'],wave:['gravity','rolls','islandwake']};const first=type==='unknown'?'Identify the instrument before interpreting color or shape. Find the source legend and product name.':type==='satellite'?'Record the satellite, channel, and whether the image uses visible, infrared, or a composite. It is not a radar echo.':type==='photo'?'Locate the original photograph or video, shooting direction, time, and weather context. A camera image cannot supply radar variables.':'Record the radar site, product, elevation, units, and exact UTC timestamp. Different radar products answer different questions.';$('#investigation-output').innerHTML=`<div class="investigation-result"><span class="kicker">NEXT CHECKS / NO AUTOMATED VERDICT</span><ol><li>${context==='missing'?'Recover the uncropped original and sequence. An unverified timestamp prevents a reliable event match.':'Verify that the displayed timestamp belongs to the event being claimed; preserve the original sequence.'}</li><li>${first}</li><li>Watch motion over time. Compare at least one independent observation: nearby radar, satellite, surface station, camera, or agency record.</li><li>Write down what was observed separately from what the caption claims caused it. List evidence that would distinguish competing explanations.</li></ol><p class="prose">Related hypotheses to investigate—not a diagnosis:</p><div class="row">${routes[shape].map(id=>`<button class="button secondary" data-phenomenon="${id}">${phenomenonById(id).title} ↗</button>`).join('')}</div></div>`;bindExtendedLinks();}
async function copyText(text){try{await navigator.clipboard.writeText(text);notifyCopy('Copied with source links.')}catch{notifyCopy('Clipboard unavailable. Select the response below.');const el=document.createElement('textarea');el.className='copy-fallback';el.value=text;el.setAttribute('aria-label','Copy this sourced explanation');$('#page').appendChild(el);el.focus();el.select();}}
function notifyCopy(msg){$$('.copy-status').forEach(e=>e.textContent=msg);$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function bindExtendedLinks(){$$('[data-phenomenon]').forEach(b=>b.onclick=()=>{clearAtlasTimer();if(state.page!=='atlas')go('atlas');atlasDetail(b.dataset.phenomenon)});$$('[data-myth]').forEach(b=>b.onclick=()=>mythDetail(b.dataset.myth));$$('[data-copy-link]').forEach(b=>b.onclick=()=>copyText(location.origin+location.pathname+'#'+b.dataset.copyLink));$$('[data-copy-note]').forEach(b=>b.onclick=()=>{const p=phenomenonById(b.dataset.copyNote);copyText(`${p.title}: ${p.cause} ${p.trap}\nCheck: ${p.check}\nSources:\n${p.refs.map(k=>sources[k][1]).join('\n')}\nField note: ${location.origin+location.pathname}#atlas/${p.id}`)});$$('[data-copy-myth]').forEach(b=>b.onclick=()=>{const m=myths.find(m=>m.id===b.dataset.copyMyth);copyText(`${m.fact} ${m.reason}\nHow to check: ${m.test}\nSources:\n${m.refs.map(k=>sources[k][1]).join('\n')}\nThis addresses the general claim; it does not identify an unseen image.`)});}
