let selectedState='FL',regionSetting='all',compareState='TX';
function localPicks(s){const order={coast:['seabreeze','seaclutter','ap'],mountains:['blockage','orographic','terrainclutter','mountainwave'],lakes:['lakebreeze','birdroost'],volcanic:['ash'],island:['islandwake','orographic','mountainwave'],plains:['dryline','turbines','hailspike'],desert:['dust','virga'],south:['batroost'],interior:['virga','brightband','birdroost']};return [...new Set(['volcanic','island','mountains','lakes','desert','plains','coast','south','interior'].filter(t=>s.tags.includes(t)).flatMap(t=>order[t]||[]))].map(phenomenonById)}
function regionalPage(){return pageHead('07 / EXPLORE BY STATE','Different places.<br><em>Different clues.</em>','Click a state to explore the effects its geography makes worth understanding. Compare places, then follow the source-backed mechanisms.','50 STATES + DC + PUERTO RICO')+`<div class="callout"><b>A regional learning map, not a frequency map.</b> Highlights are editorial suggestions based on physical settings. They are not occurrence statistics, live detections, eruption forecasts, or claims that every part of a state shares the same conditions.</div><div class="regional-grid space"><div class="panel pad map-panel"><div class="section-top"><span class="kicker">U.S. STATE TILE MAP</span><span class="scan-badge">SCHEMATIC GEOGRAPHY</span></div><div class="filters region-filters">${[['all','All settings'],['coast','Coasts'],['mountains','Terrain'],['lakes','Great Lakes'],['volcanic','Volcano context'],['desert','Arid land'],['plains','Plains']].map(([v,l])=>`<button class="filter ${regionSetting===v?'active':''}" data-setting="${v}">${l}</button>`).join('')}</div><div class="state-map" aria-label="Clickable schematic map of U.S. states, DC, and Puerto Rico">${stateRows.map(s=>`<button class="state-tile ${selectedState===s.id?'selected':''} ${regionSetting==='all'||s.tags.includes(regionSetting)?'relevant':'muted'}" style="grid-column:${s.x+1};grid-row:${s.y+1}" data-state="${s.id}" aria-label="Explore ${s.name}" aria-pressed="${selectedState===s.id}" title="${s.name}">${s.id}</button>`).join('')}</div><p class="tip">Tiles preserve an approximate regional arrangement; they are not state outlines or radar footprints. AK, HI, and PR are inset. Dimmed states remain selectable.</p><label class="form-label" for="state-picker">OR CHOOSE FROM THE COMPLETE LIST</label><select id="state-picker" class="form-select">${[...stateRows].sort((a,b)=>a.name.localeCompare(b.name)).map(s=>`<option value="${s.id}" ${selectedState===s.id?'selected':''}>${s.name}</option>`).join('')}</select></div><div id="state-detail">${stateDetailHTML()}</div></div><div class="panel pad space"><span class="kicker">COMPARE SETTINGS</span><div class="compare-heading"><h2 id="compare-title">${stateRows.find(s=>s.id===selectedState).name} alongside…</h2><select class="form-select" id="compare-state" aria-label="Compare with another state">${[...stateRows].sort((a,b)=>a.name.localeCompare(b.name)).map(s=>`<option value="${s.id}" ${compareState===s.id?'selected':''}>${s.name}</option>`).join('')}</select></div><div id="regional-comparison">${regionComparisonHTML()}</div></div><div class="panel pad space"><span class="kicker">NEARLY EVERYWHERE / NOT PLACE-SPECIFIC</span><h3>Every state shares some interpretation challenges.</h3><p>Sun spikes, interference, biological echoes, outflow boundaries, melting-layer effects, and sampling limits cross state lines. Visibility depends on the radar, season, scatterers, and atmospheric conditions.</p><div class="row">${['sunspike','interference','insects','outflow','brightband','alias'].map(id=>`<button class="filter" data-phenomenon="${id}">${phenomenonById(id).title} ↗</button>`).join('')}</div></div><div class="source-strip"><span class="kicker">HOW THIS MAP WAS BUILT</span><p class="tip">State assignments are a qualitative synthesis of geography and the linked physical mechanisms. Volcanic context does not mean a current eruption or that a local weather radar can detect one. No measured prevalence ranking is supplied.</p>${['terrain','sea','lake','ash','dust','dryline'].map(ref).join('')}</div>`;}
function stateDetailHTML(){const s=stateRows.find(s=>s.id===selectedState),d=documentedRegional[s.id]||[];return `<div class="panel pad state-card"><div class="section-top"><span class="kicker">${s.id} / REGIONAL FIELD NOTES</span><button class="text-button" data-copy-link="regions/${s.id}">Copy link ↗</button></div><h2>${s.name}</h2><div class="setting-tags">${s.tags.map(t=>`<span>${settingNames[t]}</span>`).join('')}</div><p class="tip">Suggested topics for these settings—not a ranked list of the state’s most frequent echoes.</p><div class="regional-picks">${localPicks(s).slice(0,6).map(p=>`<button data-phenomenon="${p.id}"><span>${p.title}</span><small>${p.instrument}</small><b>↗</b></button>`).join('')}</div><div class="regional-records"><span class="kicker">DOCUMENTED LOCAL RECORDS</span>${d.length?d.map(([id,text])=>`<button class="record-link" data-phenomenon="${id}">${text} ↗</button>`).join(''):'<p class="tip">No event-specific record has been curated for this state yet. The linked mechanisms remain useful starting points.</p>'}</div><span class="copy-status" aria-live="polite"></span></div>`;}
function regionComparisonHTML(){const a=stateRows.find(s=>s.id===selectedState),b=stateRows.find(s=>s.id===compareState),common=a.tags.filter(t=>b.tags.includes(t));return `<div class="state-compare-cards">${[a,b].map(s=>`<div><h3>${s.name}</h3><p>${s.tags.map(t=>settingNames[t]).join(' · ')}</p><div class="row">${localPicks(s).slice(0,4).map(p=>`<button class="filter" data-phenomenon="${p.id}">${p.title} ↗</button>`).join('')}</div></div>`).join('')}</div><p class="tip">Shared settings: ${common.length?common.map(t=>settingNames[t]).join(', '):'none among the selected editorial categories'}. Differences in setting suggest different questions to investigate; this comparison does not quantify how often phenomena occur.</p>`;}
function bindRegions(){$$('[data-state]').forEach(b=>b.onclick=()=>selectState(b.dataset.state));$$('[data-setting]').forEach(b=>b.onclick=()=>{regionSetting=b.dataset.setting;render()});$('#state-picker').onchange=e=>selectState(e.target.value);$('#compare-state').onchange=e=>{compareState=e.target.value;$('#regional-comparison').innerHTML=regionComparisonHTML();bindExtendedLinks()};bindExtendedLinks();}
function selectState(id){selectedState=id;history.replaceState(null,'','#regions/'+id);$$('[data-state]').forEach(b=>{b.classList.toggle('selected',b.dataset.state===id);b.setAttribute('aria-pressed',b.dataset.state===id)});$('#state-picker').value=id;$('#state-detail').innerHTML=stateDetailHTML();$('#compare-title').textContent=stateRows.find(s=>s.id===id).name+' alongside…';$('#regional-comparison').innerHTML=regionComparisonHTML();bindExtendedLinks();}
const observedRecords={ash:{title:'Redoubt, Alaska · March 23–April 4, 2009',kind:'ORIGINAL RESEARCH · TRANSPORTABLE C-BAND DOPPLER RADAR',text:'USGS researchers recorded explosive events with a transportable Doppler radar. This documents eruption-column detection under those conditions, not the ability of every NEXRAD site to observe every ash cloud.',source:'ash'},dust:{title:'Phoenix, Arizona · July 5, 2011',kind:'DOCUMENTED EVENT · NWS RADAR + SURFACE REPORTS',text:'NWS documented a large storm-driven dust front crossing Phoenix. Radar and ground reports were used together; echo strength alone did not establish surface visibility.',source:'dust',image:'https://www.weather.gov/images/psr/2011/July_5/dustStormPictoral.gif'},islandwake:{title:'Guadalupe Island, Mexico · May 8, 2021',kind:'DOCUMENTED EVENT · NOAA SATELLITE IMAGERY',text:'NOAA satellites observed vortices downstream of Guadalupe Island. This example is a satellite cloud observation, not a Doppler radar scan.',source:'wake',video:'https://www.nesdis.noaa.gov/s3dl?path=%2Fs3%2F2021-07%2F2021_05_13_vonKarmanVortices_UHD.mp4'},dryline:{title:'Southeast Wyoming and northern Colorado · June 22, 2010',kind:'ORIGINAL RESEARCH · RADAR + SURFACE OBSERVATIONS',text:'A published observational/modeling study compared a radar fine line with contrasting air masses and surface dewpoints.',source:'dryline'},seabreeze:{title:'Mississippi coast · August 2014 and 2015',kind:'ORIGINAL RESEARCH · RADAR + MOBILE SURFACE OBSERVATIONS',text:'A field study compared identifiable sea-breeze radar fine lines with observed changes across the boundary.',source:'seabreezeStudy'}};
sources.seabreezeStudy=['Original study · Gulf of Mexico sea-breeze fronts','https://repository.library.noaa.gov/view/noaa/23259'];
function renderObserved(p){const r=observedRecords[p.id];if(!r)return;$('#observed-example').innerHTML=`<section class="panel pad space"><span class="kicker">${r.kind}</span><h2>${r.title}</h2><p>${r.text}</p>${r.image?`<figure class="archive"><img src="${r.image}" alt="Original NWS radar image of the July 5, 2011 Phoenix dust storm" loading="lazy"><figcaption>ORIGINAL AGENCY IMAGE · ${ref(r.source)}</figcaption></figure>`:''}${r.video?`<video class="observed-video" controls preload="none" aria-label="NOAA satellite video of Guadalupe Island vortex streets"><source src="${r.video}" type="video/mp4"></video><p class="tip">Original NOAA educational video. Historical satellite observations; no live feed. If video playback is unavailable, use the original source below.</p>`:''}${ref(r.source)}</section>`;}
function bindAtlasPage(){$('#atlas-search').oninput=e=>{atlasQuery=e.target.value;$('#atlas-results').innerHTML=atlasResults();bindExtendedLinks()};$('#atlas-instrument').onchange=e=>{atlasInstrument=e.target.value;$('#atlas-results').innerHTML=atlasResults();bindExtendedLinks()};$$('[data-atlas-filter]').forEach(b=>b.onclick=()=>{atlasFilter=b.dataset.atlasFilter;render()});bindExtendedLinks();}
function bindMythsPage(){$('#myth-search').oninput=e=>{mythQuery=e.target.value;$('#myth-results').innerHTML=mythResults();bindExtendedLinks()};$$('[data-myth-filter]').forEach(b=>b.onclick=()=>{mythFilter=b.dataset.mythFilter;render()});$('#jump-investigate').onclick=()=>$('#investigate').scrollIntoView({behavior:'smooth'});$('#investigate-run').onclick=runInvestigation;$('#copy-checklist').onclick=()=>copyText('Weather screenshot checklist:\n1. Recover the original image and sequence.\n2. Identify radar, satellite, or camera; product/channel, location, time, and units.\n3. Compare other products and independent observations.\n4. Separate observations from causal claims.\n5. Test competing explanations and retain uncertainty.\nGuide: '+location.origin+location.pathname+'#myths');bindExtendedLinks();}
glossary.push(
['Sea-breeze front','The advancing edge of a local circulation driven by land–water temperature contrasts; concentrated insects can make it visible as a radar fine line.'],
['Lake breeze','A similar local circulation adjacent to a lake, with cooler air flowing onshore under suitable conditions.'],
['Orographic precipitation','Precipitation shaped or enhanced by airflow rising over terrain. A radar shadow is an observing limitation, not the same thing as a physical rain shadow.'],
['Tephra','Fragmented material ejected by a volcanic eruption, including ash and larger particles. Radar sensitivity depends on particle properties and observing geometry.'],
['Von Kármán vortex street','A repeating pattern of alternating vortices in the wake of an obstacle; island cloud examples are commonly satellite observations.'],
['Atmospheric gravity wave','An oscillation in stratified air restored by buoyancy and gravity. It is different from a gravitational wave in spacetime.'],
['Haboob','A dust storm caused by strong thunderstorm outflow lifting sediment from dry ground.'],
['Convergence','Airflow coming together, potentially concentrating scatterers and helping force air upward.'],
['Outflow boundary','The edge of air cooled by a thunderstorm spreading into surrounding air. It can persist after the parent storm weakens.'],
['Contrail','An aircraft condensation trail of ice crystals whose persistence depends on upper-air temperature and humidity.'],
['Fallstreak hole','A gap in suitable supercooled cloud associated with ice formation and falling crystals; an aircraft can trigger the process.'],
['Cloud seeding','An attempt to influence precipitation processes in suitable existing clouds by introducing selected particles. Its existence does not establish hurricane control.']
);
const baseRender=render;
render=function(){if(['atlas','regions','myths'].includes(state.page)){$('#page').innerHTML=({atlas:atlasPage,regions:regionalPage,myths:mythsPage})[state.page]();bind();({atlas:bindAtlasPage,regions:bindRegions,myths:bindMythsPage})[state.page]();}else{baseRender();if(state.page==='explore'){const el=document.createElement('section');el.className='new-wing space';el.innerHTML=`<div><span class="kicker">THE EXPANDED FIELDGUIDE</span><h2>Follow the oddities.<br><em>Question the captions.</em></h2><p>30 signatures. A state-by-state learning map. 15 evidence-based claim files.</p></div><div class="new-wing-links"><button data-go="atlas"><span>06 / SIGNATURE ATLAS</span>Mountains, volcanoes, islands & more ↗</button><button data-go="regions"><span>07 / REGIONAL MAP</span>Start with your state ↗</button><button data-go="myths"><span>08 / THE MYTH DESK</span>Unpick the viral weather claim ↗</button></div>`;$('#page').appendChild(el);bind();}}};
const baseGo=go;
go=function(page){clearAtlasTimer();activePhenomenon=null;history.replaceState(null,'','#'+page);baseGo(page)};
function restoreRoute(){const [page,id]=location.hash.replace(/^#/,'').split('/');if(['explore','basics','doppler','beam','cases','products','quiz','library','atlas','regions','myths'].includes(page)){go(page);if(page==='atlas'&&id)atlasDetail(id);if(page==='myths'&&id)mythDetail(id);if(page==='regions'&&stateRows.some(s=>s.id===id))selectState(id);}}
window.addEventListener('hashchange',restoreRoute);if(location.hash&&location.hash!=='#')restoreRoute();else render();
